import {
    Asset,
    Color,
    Entity,
    Mesh,
    MeshInstance,
    Quat,
    Ray,
    StandardMaterial,
    TorusGeometry,
    Vec3
} from 'playcanvas';

import { EntityTransformOp } from './edit-ops';
import { Events } from './events';
import type { Scene } from './scene';
import { Transform } from './transform';

// Director console (导演台) v10: animated character puppets are first-class
// scene objects alongside splats. Each puppet is wrapped in a Splat-shaped
// adapter so SS's own transform gizmos, pivot pipeline and undo/redo history
// (EntityTransformOp) operate on puppets with zero changes to SS tool code.
// UI lives in the APK override layer (www/dock.js) and talks to this module
// through window.__director + 'director-state' DOM events.

type Clip = {
    index: number;
    state: string;
    label: string;
    track: any;
};

type Puppet = {
    id: number;
    name: string;
    entity: Entity;
    anim: any;
    clip: number;
    playing: boolean;
    marker: Entity;
    adapter: PuppetAdapter;
};

type DirectorMode = 'none' | 'place-puppet' | 'place-cursor' | 'select-puppet';

const GLB_URL = 'static/director/character.glb';
const TAP_MAX_MS = 600;
const TAP_MAX_DIST = 8;          // px, tap vs drag
const SELECT_RADIUS = 0.15;      // normalized screen units for tap-select
const PUPPET_PROBE_Y = [0.15, 1.0, 1.6]; // feet/chest/head pick probes (m)
const CURSOR_Y_LIFT = 0.02;      // lift above snapped surface against z-fighting
const PUPPET_SPACING = 0.9;      // m, auto-row shift when target spot is taken

class PuppetAdapter {
    // duck-type marker: this is a puppet, not a splat
    isPuppet = true;
    puppet: Puppet;
    scene: Scene;
    entity: Entity;

    constructor(puppet: Puppet, scene: Scene) {
        this.puppet = puppet;
        this.scene = scene;
        this.entity = puppet.entity;
    }

    // EntityTransformHandler pushes the splats-handler when numSelected > 0;
    // puppets have no per-splat selection so it is always the entity path
    get numSelected() {
        return 0;
    }

    // defensive stubs: splat-only tools may probe these when a puppet happens
    // to be the current selection; neutral values keep them inert
    measureData: any = null;
    orientSelection = -1;
    localFrame: any = null;

    // per-frame pipeline reads selectedSplat?.instances.numSelected
    // (projected-splat-renderer); without this stub every frame throws and
    // kills the render loop (v10 black-screen bug)
    private _instancesStub = { numSelected: 0 };

    get instances() {
        return this._instancesStub;
    }

    // bound-dimensions overlay reads selection.localBound {center, halfExtents}
    // every prerender while enabled; puppet entities sit directly under app.root
    // so world mesh aabbs equal local-space bounds
    get localBound(): { center: Vec3, halfExtents: Vec3 } {
        const min = new Vec3();
        const max = new Vec3();
        let any = false;
        const meshInstances = [] as any[];
        (this.entity.findComponents('render') as any[]).forEach((rc) => {
            (rc.meshInstances || []).forEach((mi: any) => meshInstances.push(mi));
        });
        meshInstances.forEach((mi) => {
            const a = mi.aabb;
            if (!any) {
                min.copy(a.min);
                max.copy(a.max);
                any = true;
            } else {
                min.x = Math.min(min.x, a.min.x); min.y = Math.min(min.y, a.min.y); min.z = Math.min(min.z, a.min.z);
                max.x = Math.max(max.x, a.max.x); max.y = Math.max(max.y, a.max.y); max.z = Math.max(max.z, a.max.z);
            }
        });
        if (!any) {
            return { center: new Vec3(0, 0.9, 0), halfExtents: new Vec3(0.01, 0.01, 0.01) };
        }
        const center = new Vec3((min.x + max.x) / 2, (min.y + max.y) / 2, (min.z + max.z) / 2);
        const halfExtents = new Vec3((max.x - min.x) / 2, (max.y - min.y) / 2, (max.z - min.z) / 2);
        return { center, halfExtents };
    }

    // pivot = the puppet's local frame (entity transform)
    getPivot(result: Transform) {
        result.set(this.entity.getLocalPosition(), this.entity.getLocalRotation(), this.entity.getLocalScale());
    }

    // driven by the transform gizmo through EntityTransformOp (incl. undo/redo)
    move(position: Vec3, rotation: Quat, scale: Vec3) {
        this.entity.setLocalPosition(position);
        this.entity.setLocalRotation(rotation);
        this.entity.setLocalScale(scale);
        this.scene.forceRender = true;
    }

    get visible() {
        return this.entity.enabled;
    }

    set visible(value: boolean) {
        this.entity.enabled = value;
        this.scene.forceRender = true;
    }

    get name() {
        return this.puppet.name;
    }

    get worldTransform() {
        return this.entity.getWorldTransform();
    }
}

// undo/redo op for adding a puppet
class PuppetAddOp {
    name = 'puppetAdd';
    director: Director;
    pos: Vec3;
    puppet: Puppet | null = null;

    constructor(director: Director, pos: Vec3) {
        this.director = director;
        this.pos = pos;
    }

    do() {
        this.puppet = this.director.spawnPuppet(this.pos, this.puppet?.name);
        if (this.puppet) {
            this.director.selectPuppet(this.puppet);
        }
    }

    undo() {
        if (this.puppet) {
            this.director.destroyPuppet(this.puppet);
        }
    }

    destroy() {
        this.puppet = null;
        this.director = null;
    }
}

// undo/redo op for deleting a puppet
class PuppetDeleteOp {
    name = 'puppetDelete';
    director: Director;
    puppet: Puppet | null = null;
    pos: Vec3;
    puppetName: string;
    clip: number;

    constructor(director: Director, puppet: Puppet) {
        this.director = director;
        this.puppet = puppet;
        const e = puppet.entity;
        this.pos = e.getLocalPosition().clone();
        this.puppetName = puppet.name;
        this.clip = puppet.clip;
    }

    do() {
        this.director.destroyPuppet(this.puppet!);
    }

    undo() {
        const p = this.director.spawnPuppet(this.pos, this.puppetName);
        if (p && this.clip >= 0) {
            this.director.playClip(this.clip, p);
        }
    }

    destroy() {
        this.puppet = null;
        this.director = null;
    }
}

class Director {
    events: Events;
    scene: Scene;
    mode: DirectorMode = 'none';
    puppets: Puppet[] = [];
    selectedId: number | null = null;
    private nextId = 1;
    cursorRoot: Entity | null = null;
    clips: Clip[] = [];
    loaded = false;
    private loading = false;
    private pendingAdd = false;
    private pendingArm = false;
    private tapStart: { x: number, y: number, t: number } | null = null;
    private template: any = null;

    constructor(events: Events, scene: Scene) {
        this.events = events;
        this.scene = scene;

        this.buildLights();
        this.buildCursor();
        this.bindPointer();

        // unified selection: splat selection from anywhere (scene panel,
        // SS tools) clears the puppet selection marker
        events.on('selection.changed', (sel: any) => {
            if (!sel || !sel.isPuppet) {
                if (this.selectedId !== null) {
                    this.selectedId = null;
                    this.refreshMarkers();
                    this.notify('select');
                }
            }
        });

        // scene reset: puppets are not part of the document archive, wipe them
        events.on('scene.clear', () => {
            this.puppets.slice().forEach((p) => this.destroyPuppet(p, true));
            this.selectedId = null;
            this.notify('puppet');
        });

        // GLB (7.3MB) is lazy-loaded on first director tool use to keep editor
        // startup unaffected.
        this.scene.app.on('update', () => {
            if (this.puppets.some(p => p.playing)) {
                this.scene.forceRender = true;
            }
        });
    }

    // ----- setup -----

    // SS is a splat-only scene with no lights; a StandardMaterial puppet would
    // render pitch black. Lights do not affect splats (custom shader) or the
    // unlit grid, only the puppet meshes.
    private buildLights() {
        const app = this.scene.app;
        const sun = new Entity('director-sun');
        sun.addComponent('light', {
            type: 'directional',
            color: new Color(1, 1, 1),
            intensity: 1.2,
            castShadows: false
        } as any);
        sun.setLocalEulerAngles(-45, 30, 0);
        app.root.addChild(sun);
        (app.scene as any).ambientLight = new Color(0.45, 0.45, 0.5);
    }

    private unlitMat(color: Color) {
        const mat = new StandardMaterial();
        mat.useLighting = false;
        mat.emissive = color;
        mat.diffuse = new Color(0, 0, 0);
        mat.update();
        return mat;
    }

    private whiteMat: StandardMaterial | null = null;
    private buildSharedWhiteMat() {
        if (!this.whiteMat) {
            this.whiteMat = this.unlitMat(new Color(1, 1, 1));
        }
        return this.whiteMat;
    }

    // Blender-style 3D cursor: white ball + 3-axis cross + horizontal ring.
    private buildCursor() {
        const root = new Entity('director-cursor');

        const sphere = new Entity('cursor-ball');
        sphere.addComponent('render', { type: 'sphere' } as any);
        const sphereMat = new StandardMaterial();
        sphereMat.useLighting = false;
        sphereMat.emissive = new Color(1, 1, 1);
        sphereMat.update();
        (sphere.render as any).material = sphereMat;
        sphere.setLocalScale(0.05, 0.05, 0.05);
        root.addChild(sphere);

        const white = this.buildSharedWhiteMat();
        const axisLine = (scale: [number, number, number]) => {
            const e = new Entity('cursor-line');
            e.addComponent('render', { type: 'box' } as any);
            const mi = new MeshInstance((e.render as any).meshInstances[0].mesh, white);
            (e.render as any).meshInstances = [mi];
            e.setLocalScale(scale[0], scale[1], scale[2]);
            return e;
        };
        root.addChild(axisLine([0.24, 0.007, 0.007]));
        root.addChild(axisLine([0.007, 0.007, 0.24]));
        root.addChild(axisLine([0.007, 0.24, 0.007]));

        const ring = new Entity('cursor-ring');
        ring.addComponent('render', { type: 'box' } as any);
        const ringMesh = new MeshInstance(
            Mesh.fromGeometry(this.scene.app.graphicsDevice, new TorusGeometry({ tubeRadius: 0.007, ringRadius: 0.11 })),
            white
        );
        (ring.render as any).meshInstances = [ringMesh];
        root.addChild(ring);

        root.setLocalPosition(0, CURSOR_Y_LIFT, 0);
        this.scene.app.root.addChild(root);
        this.cursorRoot = root;
    }

    // flat disc under a puppet; yellow when selected, hidden otherwise
    private buildMarker(): Entity {
        const marker = new Entity('puppet-marker');
        marker.addComponent('render', { type: 'sphere' } as any);
        const mat = new StandardMaterial();
        mat.useLighting = false;
        mat.emissive = new Color(1, 0.8, 0.1);
        mat.update();
        (marker.render as any).material = mat;
        marker.setLocalScale(0.55, 0.02, 0.55);
        marker.setLocalPosition(0, 0.012, 0);
        marker.enabled = false;
        return marker;
    }

    private bindPointer() {
        // capture phase beats SS camera/select tools; armed modes swallow the
        // WHOLE gesture (down + up) so the controller touches map stays clean
        const container = document.getElementById('canvas-container') || this.scene.canvas;
        container.addEventListener('pointerdown', (e: PointerEvent) => {
            if (this.mode === 'none') return;
            this.tapStart = { x: e.clientX, y: e.clientY, t: Date.now() };
            e.stopPropagation();
        }, true);
        container.addEventListener('pointerup', (e: PointerEvent) => {
            if (this.mode === 'none' || !this.tapStart) return;
            const start = this.tapStart;
            this.tapStart = null;
            e.stopPropagation();
            e.preventDefault();
            const dist = Math.hypot(e.clientX - start.x, e.clientY - start.y);
            if (dist > TAP_MAX_DIST || Date.now() - start.t > TAP_MAX_MS) {
                return; // drag: ignore, stay armed
            }
            this.handleTap(e.clientX, e.clientY).catch(err => console.warn(`[director] tap: ${err?.message || err}`));
        }, true);
    }

    private async handleTap(sx: number, sy: number) {
        if (this.mode === 'select-puppet') {
            await this.selectAtScreen(sx, sy);
            return;
        }
        const pos = await this.snapPosition(sx, sy);
        if (!pos) return;
        if (this.mode === 'place-puppet') {
            this.placePuppet(pos);
        } else if (this.mode === 'place-cursor') {
            this.placeCursor(pos);
        }
    }

    // Blender-style snap priority:
    // 1. splat surface under the pointer (SS depth pick)
    // 2. y=0 ground plane
    // 3. ray parallel to ground -> closest point on the ray to world origin
    private async snapPosition(sx: number, sy: number): Promise<Vec3 | null> {
        try {
            const canvas = this.scene.canvas;
            const nx = sx / canvas.clientWidth;
            const ny = sy / canvas.clientHeight;
            const [hit] = await this.scene.camera.intersectMany([{ x: nx, y: ny }]);
            if (hit && hit.position) {
                return hit.position.clone();
            }
        } catch (e) {
            // no splats / pick unavailable -> fall through
        }
        const ground = this.pickGround(sx, sy);
        if (ground) return ground;
        return this.pickViewPlane(sx, sy);
    }

    private pickGround(sx: number, sy: number): Vec3 | null {
        const cam = this.scene.camera;
        if (!cam) return null;
        const ray = new Ray(new Vec3(), new Vec3());
        cam.getRay(sx, sy, ray);
        const o = ray.origin;
        const d = ray.direction;
        if (Math.abs(d.y) < 1e-6) return null;
        const t = -o.y / d.y;
        if (t < 0) return null;
        return o.clone().add(d.clone().mulScalar(t));
    }

    private pickViewPlane(sx: number, sy: number): Vec3 | null {
        const cam = this.scene.camera;
        if (!cam) return null;
        const ray = new Ray(new Vec3(), new Vec3());
        cam.getRay(sx, sy, ray);
        const t = -ray.origin.dot(ray.direction);
        if (t <= 0) return null;
        return ray.origin.clone().add(ray.direction.clone().mulScalar(t));
    }

    private loadCharacter() {
        const app = this.scene.app;
        const glbAsset = new Asset('director-character', 'container', { url: GLB_URL });
        app.assets.add(glbAsset);
        app.assets.load(glbAsset);
        glbAsset.on('load', () => {
            try {
                const res = glbAsset.resource;
                this.template = res;
                const anims = res.animations || [];
                this.clips = anims.map((a: any, i: number) => ({
                    index: i,
                    state: `clip_${i}`,
                    label: (a.resource && a.resource.name) || (`anim ${i}`),
                    track: a.resource
                }));
                this.loaded = true;
                this.loading = false;
                if (this.pendingAdd) {
                    this.pendingAdd = false;
                    this.pendingArm = false;
                    this.addPuppet();
                } else if (this.pendingArm) {
                    this.pendingArm = false;
                    this.mode = 'place-puppet';
                    this.notify('mode');
                }
                this.notify('loaded');
            } catch (e: any) {
                console.error(`[director] character setup failed: ${e?.message || e}`);
            }
        });
        glbAsset.on('error', (e: any) => {
            console.error(`[director] GLB load failed: ${e?.message || e}`);
        });
    }

    spawnPuppet(pos: Vec3, name?: string): Puppet | null {
        if (!this.template) return null;
        const app = this.scene.app;
        const ent: Entity = this.template.instantiateRenderEntity();
        ent.setLocalPosition(pos.x, pos.y, pos.z);
        app.root.addChild(ent);

        const anim = ent.addComponent('anim', { rootBone: ent, activate: true } as any);
        this.clips.forEach((c) => {
            try {
                anim.assignAnimation(c.state, c.track, 'Base');
            } catch (e) {
                console.warn(`[director] assignAnimation failed: ${c.label}`);
            }
        });

        const id = this.nextId++;
        const marker = this.buildMarker();
        ent.addChild(marker);

        const puppet: Puppet = {
            id,
            name: name || `人偶${id}`,
            entity: ent,
            anim,
            clip: this.defaultClipIndex(),
            playing: false,
            marker,
            adapter: null as any
        };
        puppet.adapter = new PuppetAdapter(puppet, this.scene);
        this.puppets.push(puppet);
        if (puppet.clip >= 0) {
            this.playClip(puppet.clip, puppet);
        }
        this.scene.forceRender = true;
        this.notify('puppet');
        return puppet;
    }

    private defaultClipIndex(): number {
        const idx = this.clips.findIndex(c => /^idle_loop$/i.test(c.label));
        const fallback = this.clips.findIndex(c => /^idle/i.test(c.label) && !/crouch/i.test(c.label));
        return idx >= 0 ? idx : (fallback >= 0 ? fallback : -1);
    }

    // ----- unified selection -----

    // selecting a puppet routes it into SS's selection pipeline so the native
    // transform gizmos + undo/redo operate on it; splats are selected through
    // the same event (SS native path)
    selectPuppet(p: Puppet | null) {
        this.selectedId = p ? p.id : null;
        this.refreshMarkers();
        this.scene.forceRender = true;
        this.events.fire('selection', p ? p.adapter : null);
        this.notify('select');
    }

    get selected(): Puppet | null {
        return this.puppets.find(p => p.id === this.selectedId) ?? null;
    }

    get selectedPuppet(): Puppet | null {
        return this.selected;
    }

    private refreshMarkers() {
        this.puppets.forEach((p) => {
            p.marker.enabled = p.id === this.selectedId && p.entity.enabled;
        });
    }

    // ----- public API (window.__director + dock UI) -----

    private ensureCharacter() {
        if (this.loaded) return 'ok';
        if (!this.loading) {
            this.loading = true;
            this.loadCharacter();
        }
        return 'loading';
    }

    addPuppet() {
        if (this.ensureCharacter() !== 'ok') {
            this.pendingAdd = true;
            return 'loading';
        }
        const at = (this.cursorRoot && this.cursorRoot.enabled) ?
            this.cursorRoot.getLocalPosition().clone() :
            new Vec3(0, 0, 0);
        at.y = Math.max(0, at.y - CURSOR_Y_LIFT);
        let guard = 0;
        while (this.puppets.some((p) => {
            const q = p.entity.getLocalPosition();
            return Math.hypot(q.x - at.x, q.z - at.z) < 0.6;
        }) && guard++ < 20) {
            at.x += PUPPET_SPACING;
        }
        // the op performs the spawn: edit.add applies ops through the history
        // queue (op.do), so spawning here as well would duplicate the puppet
        this.events.fire('edit.add', new PuppetAddOp(this, at));
        return 'ok';
    }

    armPlacePuppet() {
        if (this.ensureCharacter() !== 'ok') {
            this.pendingArm = true;
            return 'loading';
        }
        this.mode = (this.mode === 'place-puppet') ? 'none' : 'place-puppet';
        this.notify('mode');
        return this.mode;
    }

    armPlaceCursor() {
        this.mode = (this.mode === 'place-cursor') ? 'none' : 'place-cursor';
        this.notify('mode');
        return this.mode;
    }

    armSelect() {
        this.mode = (this.mode === 'select-puppet') ? 'none' : 'select-puppet';
        this.notify('mode');
        return this.mode;
    }

    disarm() {
        this.mode = 'none';
        this.notify('mode');
    }

    // armed tap places the selected puppet (undoable); with nothing selected
    // the first tap spawns a new puppet here
    placePuppet(pos: Vec3) {
        const p = this.selected;
        if (p) {
            const oldt = new Transform(
                p.entity.getLocalPosition().clone(),
                p.entity.getLocalRotation().clone(),
                p.entity.getLocalScale().clone()
            );
            const newt = new Transform(pos.clone(), oldt.rotation.clone(), oldt.scale.clone());
            p.entity.setLocalPosition(pos.x, pos.y, pos.z);
            this.events.fire('edit.add', new EntityTransformOp({
                splat: p.adapter as any,
                oldt,
                newt
            }));
        } else {
            if (this.ensureCharacter() === 'ok') {
                // tap-spawn also goes through the history so undo removes it
                this.events.fire('edit.add', new PuppetAddOp(this, pos.clone()));
            }
        }
        this.mode = 'none';
        this.scene.forceRender = true;
        this.notify('puppet');
    }

    placeCursor(pos: Vec3) {
        if (!this.cursorRoot) return;
        this.cursorRoot.setLocalPosition(pos.x, pos.y + CURSOR_Y_LIFT, pos.z);
        this.cursorRoot.enabled = true;
        this.mode = 'none';
        this.scene.forceRender = true;
        this.notify('cursor');
    }

    // tap-select in SCREEN SPACE over puppets first, then splats via SS depth
    // pick: one tool selects any object kind in the scene
    async selectAtScreen(sx: number, sy: number) {
        const canvas = this.scene.canvas;
        if (canvas.clientWidth === 0 || canvas.clientHeight === 0) return;
        const nx = sx / canvas.clientWidth;
        const ny = sy / canvas.clientHeight;
        const screen = new Vec3();
        let best: Puppet | null = null;
        let bestDist = SELECT_RADIUS;
        this.puppets.forEach((p) => {
            if (!p.entity.enabled) return;
            const base = p.entity.getLocalPosition();
            PUPPET_PROBE_Y.forEach((dy) => {
                this.scene.camera.worldToScreen(new Vec3(base.x, base.y + dy, base.z), screen);
                const d = Math.hypot(nx - screen.x, ny - screen.y);
                if (d < bestDist) {
                    bestDist = d;
                    best = p;
                }
            });
        });
        this.mode = 'none';
        if (best) {
            this.selectPuppet(best as Puppet);
            return;
        }
        // not a puppet: unified path selects the splat (or clears selection)
        this.selectedId = null;
        this.refreshMarkers();
        let splat: any = null;
        try {
            const hit = await this.scene.camera.intersect(nx, ny);
            splat = hit?.splat ?? null;
        } catch (e) {
            splat = null;
        }
        this.events.fire('selection', splat);
        this.notify('select');
    }

    deleteSelected() {
        const p = this.selected;
        if (!p) return 'none';
        this.events.fire('edit.add', new PuppetDeleteOp(this, p));
        this.selectPuppet(null);
        this.scene.forceRender = true;
        this.notify('puppet');
        return 'ok';
    }

    // hard destroy used by ops and scene.clear (no undo bookkeeping here)
    destroyPuppet(p: Puppet, silent = false) {
        p.entity.destroy();
        this.puppets = this.puppets.filter(x => x.id !== p.id);
        if (this.selectedId === p.id) {
            this.selectedId = null;
            this.refreshMarkers();
        }
        this.scene.forceRender = true;
        if (!silent) {
            this.notify('puppet');
        }
    }

    selectPuppetById(id: number) {
        const p = this.puppets.find(x => x.id === id);
        if (p) {
            this.selectPuppet(p);
        }
    }

    deletePuppetById(id: number) {
        const p = this.puppets.find(x => x.id === id);
        if (!p) return 'none';
        this.events.fire('edit.add', new PuppetDeleteOp(this, p));
        if (this.selectedId === id) {
            this.selectPuppet(null);
        }
        this.scene.forceRender = true;
        this.notify('puppet');
        return 'ok';
    }

    // visibility toggle from the scene sheet
    setPuppetVisible(id: number, value: boolean) {
        const p = this.puppets.find(x => x.id === id);
        if (!p) return;
        p.entity.enabled = value;
        if (!value && this.selectedId === id) {
            this.selectPuppet(null);
        } else {
            this.refreshMarkers();
        }
        this.scene.forceRender = true;
        this.notify('puppet');
    }

    playClip(index: number, target?: Puppet) {
        const p = target ?? this.selected;
        if (!p || !this.clips[index]) return;
        p.anim.playing = true;
        p.anim.baseLayer.play(this.clips[index].state);
        p.clip = index;
        p.playing = true;
        this.scene.forceRender = true;
        this.notify('clip');
    }

    pause(target?: Puppet) {
        const p = target ?? this.selected;
        if (!p) return;
        p.anim.playing = false;
        p.playing = false;
        this.notify('clip');
    }

    listClips() {
        return this.clips.map(c => ({ index: c.index, label: c.label }));
    }

    // snapshot for the scene sheet (dock.js renders the puppet rows)
    listPuppets() {
        return this.puppets.map((p) => ({
            id: p.id,
            name: p.name,
            visible: p.entity.enabled,
            selected: p.id === this.selectedId,
            clip: p.clip,
            clipLabel: p.clip >= 0 ? (this.clips[p.clip]?.label ?? null) : null,
            playing: p.playing
        }));
    }

    info() {
        const focus = this.selected ?? this.puppets[this.puppets.length - 1] ?? null;
        const pos = focus ? focus.entity.getLocalPosition() : null;
        return {
            loaded: this.loaded,
            count: this.puppets.length,
            selectedId: this.selectedId,
            selectedName: this.selected?.name ?? null,
            hasPuppet: this.puppets.length > 0,
            pos: pos ? { x: +pos.x.toFixed(2), y: +pos.y.toFixed(2), z: +pos.z.toFixed(2) } : null,
            clip: focus?.clip ?? -1,
            clipLabel: focus && focus.clip >= 0 ? (this.clips[focus.clip]?.label ?? null) : null,
            playing: focus?.playing ?? false,
            clipCount: this.clips.length,
            cursorOn: !!(this.cursorRoot && this.cursorRoot.enabled),
            mode: this.mode
        };
    }

    private notify(what: string) {
        document.dispatchEvent(new CustomEvent('director-state', {
            detail: { what, info: this.info() }
        }));
    }
}

const registerDirector = (events: Events, scene: Scene) => {
    const director = new Director(events, scene);
    events.function('director', () => director);
    (window as any).__director = director;
    (window as any).__directorInfo = () => director.info();
};

export { registerDirector, Director };
